<?php
function page_allocations(array $u):void {
 $manager=is_manager($u);$supplier=$u['role']==='supplier';
 if($manager){
 $batches=rows("SELECT b.id,b.supplier_id,b.raw_type_id,b.batch_code,r.name raw_name,s.legal_name,ROUND(b.quantity-COALESCE((SELECT SUM(a.quantity) FROM allocations a WHERE a.batch_id=b.id AND a.status<>'rejected'),0),2) remaining FROM raw_batches b JOIN raw_types r ON r.id=b.raw_type_id JOIN suppliers s ON s.id=b.supplier_id WHERE s.status='verified' HAVING remaining>0 ORDER BY b.id DESC");
 $coops=rows("SELECT c.id,c.supplier_id,c.specialty_raw_type_id,c.name,c.city FROM cooperatives c WHERE c.status='verified' ORDER BY c.name");
 $allocs=rows('SELECT a.*,b.batch_code,b.supplier_id,b.raw_type_id,r.name raw_name,c.name coop_name,s.legal_name FROM allocations a JOIN raw_batches b ON b.id=a.batch_id JOIN raw_types r ON r.id=b.raw_type_id JOIN cooperatives c ON c.id=a.coop_id JOIN suppliers s ON s.id=b.supplier_id ORDER BY a.id DESC');
 }elseif($supplier){
 $allocs=rows('SELECT a.*,b.batch_code,r.name raw_name,c.name coop_name,s.legal_name FROM allocations a JOIN raw_batches b ON b.id=a.batch_id JOIN raw_types r ON r.id=b.raw_type_id JOIN cooperatives c ON c.id=a.coop_id JOIN suppliers s ON s.id=b.supplier_id WHERE b.supplier_id=? ORDER BY a.id DESC',[$u['supplier_id']]);
 }else{
 $allocs=rows('SELECT a.*,b.batch_code,r.name raw_name,c.name coop_name,s.legal_name FROM allocations a JOIN raw_batches b ON b.id=a.batch_id JOIN raw_types r ON r.id=b.raw_type_id JOIN cooperatives c ON c.id=a.coop_id JOIN suppliers s ON s.id=b.supplier_id WHERE a.coop_id=? ORDER BY a.id DESC',[$u['coop_id']]);
 }
 if($manager):?><div class="panel panel-pad mb-4 form-card"><h5>Alokasikan bahan mentah</h5><p class="helper">Hanya dapat mengalokasikan ke koperasi terverifikasi dari PT yang sama dan dengan spesialisasi limbah yang sesuai. Alokasi menahan kuantitas bahan sampai koperasi menolak atau memprosesnya.</p><form method="post" class="row g-3"><?=csrf_input()?><input type="hidden" name="action" value="allocate"><div class="col-md-5"><label class="form-label">Batch tersedia</label><select name="batch_id" id="batch" class="form-select" required onchange="filterCoops()"><option value="">Pilih batch</option><?php foreach($batches as $b):?><option value="<?=$b['id']?>" data-supplier="<?=$b['supplier_id']?>" data-type="<?=$b['raw_type_id']?>"><?=e($b['batch_code'].' · '.$b['raw_name'].' · '.$b['legal_name'].' (sisa '.number($b['remaining']).' kg)')?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label">Koperasi tujuan</label><select name="coop_id" id="coop" class="form-select" required><option value="">Pilih koperasi</option><?php foreach($coops as $c):?><option value="<?=$c['id']?>" data-supplier="<?=$c['supplier_id']?>" data-type="<?=$c['specialty_raw_type_id']?>"><?=e($c['name'].' · '.$c['city'])?></option><?php endforeach;?></select></div><div class="col-md-3"><?php field('Alokasi (kg)','quantity','number','','required step="0.01" min="0.01"');?></div><div class="col-12"><button class="btn btn-coco">Buat alokasi</button></div></form></div><script>function filterCoops(){let selected=document.querySelector('#batch option:checked'),opts=document.querySelectorAll('#coop option');document.getElementById('coop').value='';opts.forEach(o=>{o.hidden=!!o.value&&(o.dataset.supplier!==selected.dataset.supplier||o.dataset.type!==selected.dataset.type)})}filterCoops()</script><?php endif;?>
<div class="panel"><div class="panel-pad section-title mb-0"><h5>Riwayat alokasi · <?=count($allocs)?></h5></div><div class="table-responsive"><table class="table"><thead><tr><th>Batch</th><th>PT pemasok</th><th>Koperasi anak</th><th>Jenis limbah</th><th>Qty</th><th>Status</th><?php if($u['role']==='coop'):?><th>Respons</th><?php endif;?></tr></thead><tbody><?php foreach($allocs as $a):?><tr><td class="fw-bold"><?=e($a['batch_code'])?></td><td><?=e($a['legal_name'])?></td><td><?=e($a['coop_name'])?></td><td><?=e($a['raw_name'])?></td><td><?=number($a['quantity'])?> kg</td><td><?=badge($a['status'])?></td><?php if($u['role']==='coop'):?><td><?php if($a['status']==='proposed'){action_form('respond_allocation',(int)$a['id'],'Terima','btn-outline-coco',['status'=>'accepted']);echo ' ';action_form('respond_allocation',(int)$a['id'],'Tolak','btn-outline-danger',['status'=>'rejected']);}else echo '<span class="helper">Diproses</span>';?></td><?php endif;?></tr><?php endforeach;?></tbody></table><?php if(!$allocs)table_empty('Belum ada alokasi.');?></div></div>
<?php }
